using Alterverse.Combat;using Alterverse.Match;using UnityEngine;using UnityEngine.InputSystem;
namespace Alterverse.Characters
{
[RequireComponent(typeof(CharacterController)),RequireComponent(typeof(Health))]public sealed class HeroMotor:MonoBehaviour
{
[SerializeField,Min(.1f)]private float fallbackMoveSpeed=6.5f;[SerializeField,Min(0f)]private float rotationSpeed=18f;[SerializeField]private Transform cameraTransform;[SerializeField]private float arenaHalfWidth=41f,arenaHalfHeight=35f;private CharacterController controller;private Health health;private HeroCombatProfile profile;private PlanetBuffReceiver planetBuff;private Vector2 moveInput;private Vector3 lastMoveDirection=Vector3.forward;private bool externalInput;public Vector3 LastMoveDirection=>lastMoveDirection;public bool HasMoveInput=>moveInput.sqrMagnitude>.02f;public float MoveSpeed=>(Profile!=null?Profile.MoveSpeed:fallbackMoveSpeed)*(PlanetBuff!=null?PlanetBuff.MoveSpeedMultiplier:1f)*HeroCombatStatus.Speed(gameObject);private HeroCombatProfile Profile{get{if(profile==null)profile=GetComponent<HeroCombatProfile>();return profile;}}private PlanetBuffReceiver PlanetBuff{get{if(planetBuff==null)planetBuff=GetComponent<PlanetBuffReceiver>();return planetBuff;}}
private void Awake(){controller=GetComponent<CharacterController>();health=GetComponent<Health>();profile=GetComponent<HeroCombatProfile>();planetBuff=GetComponent<PlanetBuffReceiver>();if(cameraTransform==null&&Camera.main!=null)cameraTransform=Camera.main.transform;}private void Update(){if(Time.timeScale<=0f||health.IsDead){moveInput=Vector2.zero;externalInput=false;return;}if(!externalInput)ReadKeyboardInput();Move(moveInput);externalInput=false;}private void ReadKeyboardInput(){if(Keyboard.current==null){moveInput=Vector2.zero;return;}float x=0,y=0;if(Keyboard.current.aKey.isPressed)x-=1;if(Keyboard.current.dKey.isPressed)x+=1;if(Keyboard.current.sKey.isPressed)y-=1;if(Keyboard.current.wKey.isPressed)y+=1;moveInput=Vector2.ClampMagnitude(new Vector2(x,y),1);}public void SetMoveInput(Vector2 input){if(health!=null&&health.IsDead){moveInput=Vector2.zero;externalInput=false;return;}moveInput=Vector2.ClampMagnitude(input,1);externalInput=true;}
private void Move(Vector2 input){if(controller==null||!controller.enabled)return;Vector3 forward=cameraTransform!=null?cameraTransform.forward:Vector3.forward,right=cameraTransform!=null?cameraTransform.right:Vector3.right;forward.y=0;right.y=0;forward.Normalize();right.Normalize();Vector3 direction=Vector3.ClampMagnitude(forward*input.y+right*input.x,1);if(direction.sqrMagnitude>.001f){lastMoveDirection=direction.normalized;transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(direction,Vector3.up),rotationSpeed*Time.deltaTime);}Vector3 velocity=direction*MoveSpeed;if(!controller.isGrounded)velocity.y=-4;controller.Move(velocity*Time.deltaTime);Vector3 clamped=transform.position;clamped.x=Mathf.Clamp(clamped.x,-arenaHalfWidth,arenaHalfWidth);clamped.z=Mathf.Clamp(clamped.z,-arenaHalfHeight,arenaHalfHeight);if((clamped-transform.position).sqrMagnitude>.0001f){controller.enabled=false;transform.position=clamped;controller.enabled=true;}}
}
}
